import type { BankQuestion } from "@/lib/bank";

/** Gravitation (Physics (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-gravitation-1","question":"The value of the universal gravitational constant G in SI units is about:","options":["6.67 × 10⁻⁸ N m² kg⁻²","6.67 × 10⁻¹¹ N m² kg⁻²","6.67 × 10¹¹ N m² kg⁻²","9.8 N m² kg⁻²"],"answer":1,"explanation":"G ≈ 6.67 × 10⁻¹¹ N m² kg⁻² in SI; 6.67 × 10⁻⁸ is its value in CGS units, and 9.8 m/s² is g, a different quantity.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-2","question":"The escape speed of a body from the Earth's surface does NOT depend on:","options":["the mass of the body","the gravitational constant","the radius of the Earth","the mass of the Earth"],"answer":0,"explanation":"vₑ = √(2GM/R) contains G, the Earth's mass M and its radius R, but not the mass of the projected body, which cancels from ½mv² = GMm/R.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-gravitation-3","question":"Kepler's second law (equal areas in equal times) follows from the conservation of:","options":["linear momentum","mechanical energy","mass","angular momentum"],"answer":3,"explanation":"Gravity is a central force, so its torque about the Sun is zero and angular momentum is conserved; the areal velocity dA/dt = L/2m is therefore constant.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-gravitation-4","question":"Taking g = 10 m/s² and the radius of the Earth as 6400 km, the orbital speed of a satellite revolving just above the Earth's surface is:","options":["8 km/s","4 km/s","5.6 km/s","11.2 km/s"],"answer":0,"explanation":"v = √(gR) = √(10 × 6.4 × 10⁶) = √(6.4 × 10⁷) = 8 × 10³ m/s = 8 km/s. 11.2 km/s is the escape speed, √2 times larger.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-5","question":"The ratio of the escape speed from the Earth's surface to the orbital speed of a satellite just above the surface is:","options":["√2","1/√2","1","2"],"answer":0,"explanation":"vₑ = √(2GM/R) and v₀ = √(GM/R), so vₑ/v₀ = √2.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-gravitation-6","question":"A satellite in a circular orbit has kinetic energy K. Its total mechanical energy is:","options":["2K","K","−2K","−K"],"answer":3,"explanation":"For a circular orbit K = GMm/2r and U = −GMm/r = −2K, so E = K + U = −K. −2K is the potential energy, not the total.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-7","question":"If the Earth stopped rotating about its axis, the value of g at the equator would:","options":["decrease by ω²R","remain unchanged","increase by ω²R","become zero"],"answer":2,"explanation":"At the equator the effective value is g − ω²R because part of gravity provides the centripetal force for rotation. With ω = 0 that part is freed, so g increases by ω²R (about 0.034 m/s²). At the poles nothing would change.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-gravitation-8","question":"The gravitational potential at a point inside a thin uniform spherical shell of mass M and radius R (at distance r from the centre) is:","options":["−GM/r","−3GM/2R","−GM/R","zero"],"answer":2,"explanation":"The field inside a shell is zero, so the potential is constant inside and equal to its surface value −GM/R. Zero is the field, not the potential.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-9","question":"A planet has twice the mass and twice the radius of the Earth. If g on the Earth is 10 m/s², the value on the planet is:","options":["20 m/s²","2.5 m/s²","5 m/s²","10 m/s²"],"answer":2,"explanation":"g = GM/R², so g' = g × 2/2² = g/2 = 5 m/s².","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-gravitation-10","question":"Taking the radius of the Earth as 6400 km, the height above the surface at which the value of g is 1% less than its surface value is about:","options":["64 km","32 km","16 km","3.2 km"],"answer":1,"explanation":"For h ≪ R, g' ≈ g(1 − 2h/R). Setting 2h/R = 0.01 gives h = 0.005 × 6400 = 32 km. 64 km is the depth for a 1% decrease (g' = g(1 − d/R)).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-11","question":"A comet moves in an elliptical orbit about the Sun. At its closest approach of 2 × 10¹⁰ m its speed is 6 × 10⁴ m/s. Its speed when it is farthest from the Sun, at 1.2 × 10¹² m, is:","options":["6000 m/s","100 m/s","1000 m/s","3.6 × 10⁶ m/s"],"answer":2,"explanation":"At the extreme points the velocity is perpendicular to the radius, so conservation of angular momentum gives v₁r₁ = v₂r₂: v₂ = 6 × 10⁴ × 2 × 10¹⁰/1.2 × 10¹² = 6 × 10⁴/60 = 1000 m/s.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-gravitation-12","question":"The escape speed from the Earth's surface is 11.2 km/s. The escape speed for a body that is already at a height equal to the Earth's radius above the surface is about:","options":["7.9 km/s","11.2 km/s","15.8 km/s","5.6 km/s"],"answer":0,"explanation":"vₑ = √(2GM/r) and r doubles from R to 2R, so vₑ falls by √2: 11.2/1.414 ≈ 7.9 km/s. Halving it (5.6 km/s) wrongly treats vₑ ∝ 1/r.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-13","question":"A body is projected vertically upward from the Earth's surface with a speed equal to half the escape speed. Neglecting air resistance, the maximum height it reaches above the surface is (R = radius of the Earth):","options":["R/2","R/3","R","R/4"],"answer":1,"explanation":"v² = ¼ × 2GM/R = GM/2R. Energy: ½v² = GM/R − GM/r → GM/4R = GM/R − GM/r → r = 4R/3, so h = R/3. Using h = v²/2g with constant g gives R/4, which ignores the weakening of gravity.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-14","question":"Three particles, each of mass m, are placed at the corners of an equilateral triangle of side a. The work needed to separate them to infinite distances from one another is:","options":["3Gm²/2a","Gm²/a","−3Gm²/a","3Gm²/a"],"answer":3,"explanation":"There are three pairs, each with potential energy −Gm²/a, so U = −3Gm²/a. The work done by the external agent to make U zero is +3Gm²/a.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-15","question":"If the radius of a satellite's circular orbit is increased by 1%, its period of revolution increases by about:","options":["1%","3%","1.5%","0.5%"],"answer":2,"explanation":"Kepler's third law: T ∝ r^(3/2), so ΔT/T = (3/2)(Δr/r) = 1.5%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-gravitation-16","question":"The gravitational field on the axis of a thin uniform ring of radius R is maximum at a distance from the centre of the ring equal to:","options":["R/√2","R","√2 R","R/2"],"answer":0,"explanation":"E = GMx/(R² + x²)^(3/2). Setting dE/dx = 0 gives R² + x² = 3x², i.e. x = R/√2. At the centre (x = 0) the field is zero.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-17","question":"Taking g = 10 m/s² and R = 6400 km, the Earth would have to rotate with a period of about how long for bodies at the equator to feel weightless?","options":["1.4 h","0.7 h","24 h","2.8 h"],"answer":0,"explanation":"Weightlessness at the equator needs ω²R = g, so ω = √(g/R) = √(10/6.4 × 10⁶) = 1/800 rad/s. T = 2π/ω = 1600π s ≈ 5027 s ≈ 1.4 h.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-18","question":"The mass of the Earth is 81 times that of the Moon and the distance between their centres is d. The point on the line joining them where the net gravitational field is zero lies at a distance from the Earth's centre of:","options":["0.1d","0.9d","0.5d","0.81d"],"answer":1,"explanation":"GM/x² = G(M/81)/(d − x)² → x/(d − x) = 9 → x = 9d/10 = 0.9d. 0.1d is the distance from the Moon.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-gravitation-19","question":"A body is released from rest at a height equal to the Earth's radius R = 6400 km above the surface (g = 10 m/s² at the surface). Neglecting air resistance, its speed on reaching the surface is:","options":["11.3 km/s","5.6 km/s","8 km/s","4 km/s"],"answer":2,"explanation":"½v² = GM(1/R − 1/2R) = GM/2R = gR/2, so v = √(gR) = √(6.4 × 10⁷) = 8 km/s. Using v = √(2gh) with constant g gives 11.3 km/s, which overestimates because g weakens with height.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-20","question":"A straight tunnel is dug along a diameter of the Earth (assumed uniform, radius 6400 km, g = 10 m/s²). A ball dropped into it from the surface reaches the other end of the tunnel after about:","options":["42 min","21 min","60 min","84 min"],"answer":0,"explanation":"Inside a uniform Earth the force is −(mg/R)x, so the motion is SHM with T = 2π√(R/g) = 2π × 800 s ≈ 84 min. Going from one end to the other is half a period, about 42 min.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-21","question":"How many of the following statements about a geostationary satellite are correct?\n(A) Its period of revolution equals the rotation period of the Earth.\n(B) It must orbit in the equatorial plane.\n(C) Its orbital radius is about 42,000 km from the Earth's centre.\n(D) Its orbital speed is about 7.9 km/s.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct (height ≈ 36,000 km, radius ≈ 42,000 km). D is wrong: 7.9 km/s is the speed just above the surface; at 42,000 km the speed is about 3.1 km/s. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-gravitation-22","question":"The energy required to shift a satellite of mass m from a circular orbit of radius 2R to one of radius 3R around the Earth (R = radius of the Earth, g = surface value) is:","options":["mgR/24","mgR/3","mgR/12","mgR/6"],"answer":2,"explanation":"E = −GMm/2r. ΔE = (GMm/2)(1/2R − 1/3R) = GMm/12R = mgR/12, using GM = gR². Computing only the change in potential energy gives mgR/6, twice the correct value.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-23","question":"Two stars of masses M and 2M, separated by a distance d, revolve in circular orbits about their common centre of mass under mutual gravity. The period of revolution is:","options":["2π√(d³/2GM)","2π√(3d³/GM)","2π√(d³/3GM)","2π√(d³/GM)"],"answer":2,"explanation":"For a binary, T = 2π√(d³/G(m₁ + m₂)). With m₁ + m₂ = 3M, T = 2π√(d³/3GM). Check on the lighter star: its radius is 2d/3 and G·2M/d² = ω²(2d/3) gives ω² = 3GM/d³.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-24","question":"A satellite moves in an elliptical orbit about a planet of mass M. Its nearest distance from the planet's centre is r and its farthest is 3r. Its speed at the nearest point is:","options":["√(GM/2r)","√(GM/r)","√(3GM/2r)","√(2GM/3r)"],"answer":2,"explanation":"Angular momentum: v₁r = v₂(3r). Energy: ½v₁² − GM/r = ½v₂² − GM/3r. With v₂ = v₁/3: ½v₁²(1 − 1/9) = 2GM/3r → v₁² = 3GM/2r.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-25","question":"Assuming the Earth to be a uniform sphere of radius R, the ratio of the weight of a body at a height R/2 above the surface to its weight at a depth R/2 below the surface is:","options":["1/2","8/9","9/8","4/9"],"answer":1,"explanation":"At height R/2: g' = g/(1.5)² = 4g/9. At depth R/2: g'' = g(1 − 1/2) = g/2. Ratio = (4/9)/(1/2) = 8/9.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-gravitation-26","question":"Assertion (A): An astronaut in a satellite orbiting the Earth feels weightless even though the Earth's gravity on him is not zero.\nReason (R): The astronaut and the satellite both fall freely towards the Earth with the same acceleration.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: since the floor accelerates exactly as he does, it exerts no normal force on him, and the normal force is what we feel as weight. Gravity at a typical orbital height is still about 90% of g.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-gravitation-27","question":"The minimum energy required to take a particle of mass m from the centre of a uniform solid sphere of mass M and radius R (through a narrow tunnel) to infinity is:","options":["GMm/R","GMm/2R","2GMm/R","3GMm/2R"],"answer":3,"explanation":"The potential at the centre of a uniform solid sphere is −3GM/2R, compared with −GM/R at its surface. The work needed is m × 3GM/2R. GMm/R would be enough only from the surface.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-28","question":"Match the quantity (List I) for a mass M of radius R with its value (List II). List I: (P) field inside a thin spherical shell; (Q) field inside a uniform solid sphere at distance r from the centre; (R) potential inside a thin spherical shell; (S) potential at the centre of a uniform solid sphere. List II: (1) −3GM/2R; (2) GMr/R³; (3) 0; (4) −GM/R.","options":["P-2, Q-3, R-4, S-1","P-3, Q-2, R-4, S-1","P-4, Q-2, R-3, S-1","P-3, Q-2, R-1, S-4"],"answer":1,"explanation":"Inside a shell the field is zero and the potential stays at −GM/R. Inside a solid sphere the field grows linearly, GMr/R³, and the potential at the centre is −3GM/2R, 1.5 times the surface value.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-29","question":"A satellite revolves in a circular orbit close to a planet. By what percentage must its speed be increased so that it just escapes from the planet's gravity?","options":["50%","100%","41.4%","29.3%"],"answer":2,"explanation":"Escape speed at that radius is √2 times the orbital speed, so the speed must rise by (√2 − 1) × 100 ≈ 41.4%. Doubling the kinetic energy needs only a √2 increase in speed, not 100%.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-gravitation-30","question":"Because of the Earth's rotation, the effective value of g at latitude 60° is reduced by an amount that, compared with the reduction at the equator, is:","options":["3/4 of it","1/2 of it","√3/2 of it","1/4 of it"],"answer":3,"explanation":"g' = g − ω²R cos²λ. At the equator (λ = 0) the reduction is ω²R; at 60°, cos²60° = 1/4, so the reduction is ω²R/4.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-gravitation-31", "question": "If the distance between two point masses is halved, the gravitational force between them:", "options": ["doubles", "halves", "becomes one-fourth", "becomes four times"], "answer": 3, "explanation": "F ∝ 1/r², so halving r makes F four times larger.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-gravitation-32", "question": "For a uniform spherical Earth, the acceleration due to gravity at its centre is:", "options": ["zero", "maximum", "equal to its surface value", "infinite"], "answer": 0, "explanation": "Inside a uniform sphere g = g₀(1 − d/R); at the centre d = R, so g = 0, because the pull from all sides cancels.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-gravitation-33", "question": "According to Kepler's third law, the square of a planet's period of revolution is proportional to:", "options": ["the semi-major axis", "the cube of the semi-major axis", "the square of the semi-major axis", "the square root of the semi-major axis"], "answer": 1, "explanation": "Kepler's law of periods: T² ∝ a³, where a is the semi-major axis of the elliptical orbit.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-gravitation-34", "question": "Taking the Earth as a uniform sphere of radius 6400 km and g = 10 m/s² at the surface, the value of g at the bottom of a mine 1600 km deep would be:", "options": ["2.5 m/s²", "5.0 m/s²", "7.5 m/s²", "8.0 m/s²"], "answer": 2, "explanation": "g_d = g(1 − d/R) = 10 × (1 − 1600/6400) = 10 × 0.75 = 7.5 m/s².", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-gravitation-35", "question": "A planet has the same mean density as the Earth but half its radius. A man who weighs 600 N on the Earth would weigh on that planet:", "options": ["150 N", "300 N", "1200 N", "600 N"], "answer": 1, "explanation": "g = GM/R² = (4/3)πGρR, so at equal density g ∝ R. Half the radius gives half of g, so the weight is 300 N.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-gravitation-36", "question": "The work needed to raise a body of mass m from the Earth's surface to a height 2R above it (R = radius of the Earth, g at the surface) is:", "options": ["mgR/3", "2mgR/3", "2mgR", "mgR/2"], "answer": 1, "explanation": "W = GMm(1/R − 1/3R) = 2GMm/3R = 2mgR/3 (using GM = gR²). Using mgh = 2mgR assumes g stays constant up to that height, which is wrong.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-gravitation-37", "question": "Two satellites revolve around the Earth in circular orbits of radii r and 2r. The ratio of their orbital speeds (inner : outer) is:", "options": ["1 : √2", "2 : 1", "√2 : 1", "1 : 2"], "answer": 2, "explanation": "v = √(GM/r), so v₁/v₂ = √(2r/r) = √2. The inner satellite moves faster.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-gravitation-38", "question": "A planet has twice the mass of the Earth and eight times its radius. If the escape speed from the Earth is 11.2 km/s, that from the planet is:", "options": ["22.4 km/s", "5.6 km/s", "2.8 km/s", "11.2 km/s"], "answer": 1, "explanation": "v_e = √(2GM/R) ∝ √(M/R) = √(2/8) = 1/2 of the Earth's value, i.e. 5.6 km/s.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-gravitation-39", "question": "The gravitational potential in a region is V = (4x + 3y) J/kg, with x and y in metres. The magnitude of the gravitational force on a 2 kg body in this region is:", "options": ["5 N", "7 N", "14 N", "10 N"], "answer": 3, "explanation": "Field = −grad V = −(4 î + 3 ĵ) N/kg, magnitude √(16 + 9) = 5 N/kg; force on 2 kg = 10 N. 5 N is the field, not the force.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-40", "question": "A satellite moves in a circular orbit around a planet. If its orbital radius were made four times, its angular momentum about the planet's centre would become:", "options": ["twice", "four times", "half", "eight times"], "answer": 0, "explanation": "L = mvr = m√(GM/r) · r = m√(GMr), so L ∝ √r and r → 4r doubles L, even though the speed halves.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-41", "question": "A satellite of mass 200 kg revolves around the Earth in a circular orbit at a height equal to the Earth's radius (R = 6400 km, g = 10 m/s²). The minimum energy needed to make it escape from the Earth's gravity is:", "options": ["6.4 × 10⁹ J", "1.28 × 10¹⁰ J", "3.2 × 10⁹ J", "1.6 × 10⁹ J"], "answer": 2, "explanation": "At r = 2R the total energy is −GMm/(2r) = −GMm/(4R) = −mgR/4 = −200 × 10 × 6.4 × 10⁶/4 = −3.2 × 10⁹ J, so 3.2 × 10⁹ J must be supplied. 6.4 × 10⁹ J is the magnitude of its potential energy, which overlooks the kinetic energy it already has.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-42", "question": "A particle of mass m lies on the axis of a thin uniform ring of mass M and radius R, at a distance √3 R from its centre. The gravitational force on the particle is:", "options": ["GMm/(4R²)", "√3GMm/(8R²)", "√3GMm/(4R²)", "GMm/(8R²)"], "answer": 1, "explanation": "On the axis F = GMm x/(R² + x²)^(3/2). With x = √3R: (R² + 3R²)^(3/2) = 8R³, so F = GMm √3R/(8R³) = √3GMm/(8R²).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-43", "question": "A planet of mass m moves around the Sun with a constant angular momentum L about the Sun. The area swept by the line joining the Sun and the planet in a time t is:", "options": ["Lt/m", "2Lt/m", "Lt/(2m)", "mLt/2"], "answer": 2, "explanation": "Areal velocity dA/dt = r²ω/2 = L/(2m), which is constant (Kepler's second law); so the area in time t is Lt/(2m).", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-gravitation-44", "question": "A body of mass M is split into two parts of masses m and (M − m), which are then kept a fixed distance apart. The gravitational force between the parts is maximum when m/M equals:", "options": ["1/4", "1/3", "1/2", "1/√2"], "answer": 2, "explanation": "F ∝ m(M − m); dF/dm = M − 2m = 0 gives m = M/2, so the ratio is 1/2.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-gravitation-45", "question": "Two planets have mean densities ρ and 4ρ. The ratio of the periods of satellites orbiting just above their surfaces (first planet : second planet) is:", "options": ["1 : 2", "2 : 1", "4 : 1", "1 : 4"], "answer": 1, "explanation": "For a near-surface orbit T = 2π√(R³/GM) = √(3π/(Gρ)), independent of the radius. So T ∝ 1/√ρ and T₁ : T₂ = √4 : 1 = 2 : 1.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-46", "question": "A planet has the same mean density as the Earth and twice its radius. If the escape speed from the Earth is 11.2 km/s, that from the planet is:", "options": ["15.8 km/s", "22.4 km/s", "11.2 km/s", "44.8 km/s"], "answer": 1, "explanation": "v_e = √(2GM/R) = R√(8πGρ/3), so at equal density v_e ∝ R; doubling R gives 22.4 km/s. 15.8 km/s (√2 times) would follow only if the mass, not the density, were scaled with R.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-gravitation-47", "question": "A satellite revolves in a circular orbit at a height of 3R above the Earth's surface (R = 6400 km, g = 10 m/s²). Its orbital speed is:", "options": ["8 km/s", "2 km/s", "5.7 km/s", "4 km/s"], "answer": 3, "explanation": "Orbital radius r = 4R, so v = √(GM/r) = √(gR²/4R) = ½√(gR) = ½ × √(10 × 6.4 × 10⁶) = ½ × 8000 = 4000 m/s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-48", "question": "For a small height h (h ≪ R), the value of g at height h above the Earth's surface equals the value at a depth d below the surface when:", "options": ["d = h", "d = h/2", "d = 2h", "d = 4h"], "answer": 2, "explanation": "For h ≪ R, g_h ≈ g(1 − 2h/R), and inside a uniform Earth g_d = g(1 − d/R). Equating gives d = 2h.", "difficulty": "hard", "source": "NEET · JEE Main"},
  {"id": "phy-gravitation-49", "question": "A spherical cavity of radius R/2 is made in a uniform solid sphere of radius R so that the cavity touches the surface. The mass of the original sphere (before the cavity) was M. The gravitational field at a point at distance 2R from the centre of the sphere, on the line through the centres and on the side of the cavity, is:", "options": ["GM/(4R²)", "7GM/(36R²)", "GM/(18R²)", "2GM/(9R²)"], "answer": 1, "explanation": "Superposition: field of the full sphere GM/(2R)² = GM/4R² minus the field of the removed mass M/8 centred at R/2, which is at distance 3R/2: G(M/8)/(9R²/4) = GM/18R². Net = GM/R²(1/4 − 1/18) = 7GM/(36R²).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-gravitation-50", "question": "A thin uniform spherical shell of mass M and radius R has a tiny hole. A particle is released from rest at a distance 3R from the centre, on the line through the hole, and falls through the hole. Its speed on reaching the centre of the shell is:", "options": ["√(2GM/3R)", "√(2GM/R)", "2√(GM/3R)", "√(GM/R)"], "answer": 2, "explanation": "From 3R to the surface: ½v² = GM(1/R − 1/3R) = 2GM/3R, so v = √(4GM/3R) = 2√(GM/3R). Inside the shell the field is zero, so the speed stays the same up to the centre.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-51", "question": "How many of the following statements are correct (Earth taken as a uniform sphere)?\n(A) g decreases linearly with depth below the surface.\n(B) The orbital speed of a satellite depends on the satellite's mass.\n(C) The total mechanical energy of a satellite in a bound orbit is negative.\n(D) The binding energy of a satellite of mass m in a circular orbit of radius r is GMm/2r.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct: g_d = g(1 − d/R), the total energy is −GMm/2r and its magnitude is the binding energy. B is wrong: v = √(GM/r) does not contain the satellite's mass.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-gravitation-52", "question": "Assertion (A): If the Earth suddenly shrank to half its present radius with its mass unchanged, the length of the day would become 6 hours.\nReason (R): In the absence of an external torque, the angular momentum of the Earth about its axis remains constant.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "With I = (2/5)MR², halving R makes I one-fourth; since Iω is conserved, ω becomes 4 times and the day 24/4 = 6 h. R is the principle that gives A, so it is the correct explanation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-gravitation-53", "question": "For a satellite in a circular orbit of radius r, match each quantity (List I) with how it varies with r (List II). List I: (P) orbital speed; (Q) period; (R) kinetic energy; (S) angular momentum. List II: (1) r⁻¹; (2) r^(1/2); (3) r^(−1/2); (4) r^(3/2).", "options": ["P-3, Q-4, R-1, S-2", "P-2, Q-4, R-1, S-3", "P-3, Q-2, R-1, S-4", "P-1, Q-4, R-3, S-2"], "answer": 0, "explanation": "v = √(GM/r) ∝ r^(−1/2); T = 2πr/v ∝ r^(3/2); K = GMm/2r ∝ r⁻¹; L = m√(GMr) ∝ r^(1/2). So P-3, Q-4, R-1, S-2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-54", "question": "A planet moves around the Sun in an elliptical orbit of eccentricity e. The ratio of its maximum speed to its minimum speed is:", "options": ["(1 + e)/(1 − e)", "(1 − e)/(1 + e)", "(1 + e)²/(1 − e)²", "√((1 + e)/(1 − e))"], "answer": 0, "explanation": "Angular momentum is conserved and at the ends of the major axis velocity ⊥ radius, so v_max r_min = v_min r_max. With r_min = a(1 − e) and r_max = a(1 + e), v_max/v_min = (1 + e)/(1 − e).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-55", "question": "A satellite in a circular orbit around the Earth experiences a small air drag. As a result, over time:", "options": ["its orbital radius decreases and its speed increases", "its orbital radius decreases and its speed decreases", "its orbital radius increases and its speed decreases", "its orbital radius and speed stay the same but its energy decreases"], "answer": 0, "explanation": "Drag removes energy, making E = −GMm/2r more negative, so r decreases. Since K = −E, the kinetic energy and speed increase; gravity does more positive work than drag takes away.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-gravitation-56", "question": "A body is projected vertically upward from the Earth's surface with a speed twice the escape speed (v_e = 11.2 km/s). Neglecting air resistance and other bodies, its speed far away from the Earth is about:", "options": ["11.2 km/s", "22.4 km/s", "19.4 km/s", "15.8 km/s"], "answer": 2, "explanation": "Energy: ½v∞² = ½(2v_e)² − GMm/R per unit mass, and GM/R = ½v_e², so v∞² = 4v_e² − v_e² = 3v_e². Hence v∞ = √3 × 11.2 ≈ 19.4 km/s, not 2v_e − v_e = 11.2 km/s.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-57", "question": "A smooth straight tunnel is dug through a uniform Earth (R = 6400 km, g = 10 m/s²) along a chord at a distance R/2 from the centre. A body released from rest at one end moves along the tunnel. Its maximum speed is about:", "options": ["8.0 km/s", "4.0 km/s", "5.7 km/s", "6.9 km/s"], "answer": 3, "explanation": "The component of gravity along the chord gives SHM with ω = √(g/R) about the chord's midpoint; the amplitude is half the chord, √(R² − R²/4) = (√3/2)R. So v_max = ωA = (√3/2)√(gR) = 0.866 × 8 km/s ≈ 6.9 km/s.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-gravitation-58", "question": "A thin uniform rod of mass M and length L lies along a line. The gravitational field it produces at a point on the same line, at a distance d from its nearer end, is:", "options": ["GM/d²", "GM/(d(d + L))", "GM/(d + L)²", "GM/(d + L/2)²"], "answer": 1, "explanation": "Integrating elements dm = (M/L)dx from x = d to d + L: E = (GM/L)(1/d − 1/(d + L)) = GM/(d(d + L)). Treating the rod as a point mass at its centre (GM/(d + L/2)²) is only approximate.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-59", "question": "For a uniform solid sphere of mass M and radius R, the ratio of the gravitational potential at a point R/2 from its centre to that at a point 2R from its centre is:", "options": ["1 : 4", "11 : 4", "3 : 1", "11 : 8"], "answer": 1, "explanation": "Inside: V = −GM(3R² − r²)/(2R³); at r = R/2, V = −GM(3 − 1/4)/(2R) = −11GM/8R. Outside at 2R: V = −GM/2R = −4GM/8R. Ratio = 11 : 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-60", "question": "If the radius of the Earth shrank by 1% with its mass unchanged, the acceleration due to gravity at the surface and the escape speed would change respectively by about:", "options": ["+2% and +0.5%", "+1% and +2%", "−2% and −0.5%", "+2% and +1%"], "answer": 0, "explanation": "g = GM/R² gives Δg/g = −2ΔR/R = +2%; v_e = √(2GM/R) gives Δv/v = −½ΔR/R = +0.5%.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"phy-gravitation-61","question":"A planet revolves round the Sun in a circular orbit with a period 8 times that of the Earth. Its orbital radius, in astronomical units (AU), is:","options":["4 AU","8 AU","2 AU","64 AU"],"answer":0,"explanation":"Kepler's third law: r³ ∝ T², so r = 8^(2/3) = 4 AU. 64 AU applies T ∝ r^(1/2) the wrong way round; 2 AU takes a cube root instead of 8^(2/3).","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-gravitation-62","question":"Taking g = 10 m/s² at the surface and the Earth's radius as 6400 km, the orbital speed of a satellite in a circular orbit at a height equal to the Earth's radius is about:","options":["8.0 km/s","5.66 km/s","4.0 km/s","11.3 km/s"],"answer":1,"explanation":"v = √(GM/r) = √(gR²/2R) = √(gR/2) = √(3.2 × 10⁷) ≈ 5.66 km/s. 8.0 km/s is the speed just above the surface; 4.0 km/s halves it instead of dividing by √2.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "phy-gravitation-63", "question": "Four particles, each of mass m, are placed at the corners of a square of side a. The gravitational potential energy of the system is:", "options": ["−4Gm²/a", "−(2 + √2)Gm²/a", "−(4 + 2√2)Gm²/a", "−(4 + √2)Gm²/a"], "answer": 3, "explanation": "There are 6 pairs: 4 sides (separation a) and 2 diagonals (separation a√2). U = −Gm²(4/a + 2/(a√2)) = −(4 + √2)Gm²/a. Counting only the sides gives −4Gm²/a.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-64", "question": "Two point masses, each M, are fixed a distance d apart in free space. The least speed with which a particle must be projected from the midpoint between them to escape to infinity is:", "options": ["√(4GM/d)", "√(8GM/d)", "√(2GM/d)", "√(16GM/d)"], "answer": 1, "explanation": "Potential at the midpoint = −2 × GM/(d/2) = −4GM/d. Escape needs ½v² = 4GM/d, so v = √(8GM/d). √(4GM/d) uses only one of the masses.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-65","question":"Taking g = 10 m/s², the Earth's radius as 6400 km and a rotation period of 24 h, the height of a geostationary satellite above the Earth's surface is about:","options":["42,600 km","6,400 km","36,000 km","3,600 km"],"answer":2,"explanation":"r³ = gR²T²/(4π²) = 10 × (6.4 × 10⁶)² × (86 400)²/(4π²), giving r ≈ 4.26 × 10⁷ m = 42,600 km from the centre. The height is r − R ≈ 36,000 km. 42,600 km is the orbital radius, not the height.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-gravitation-66", "question": "A uniform sphere of mass M contracts under its own gravity from radius R to radius R/2, staying uniform. The gravitational energy released is:", "options": ["6GM²/(5R)", "3GM²/(10R)", "GM²/(2R)", "3GM²/(5R)"], "answer": 3, "explanation": "The self-energy of a uniform sphere is U = −3GM²/(5r). U(R/2) − U(R) = −6GM²/(5R) + 3GM²/(5R) = −3GM²/(5R), so 3GM²/(5R) is released. 6GM²/(5R) is the magnitude of the final self-energy.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-gravitation-67", "question": "If the gravitational force between two masses varied as 1/r^(5/2) instead of 1/r², the period T of a satellite in a circular orbit of radius r would vary as:", "options": ["r^(7/4)", "r^(3/2)", "r^(5/4)", "r^(5/2)"], "answer": 0, "explanation": "mv²/r ∝ r^(−5/2) gives v² ∝ r^(−3/2), so v ∝ r^(−3/4) and T = 2πr/v ∝ r^(7/4). In general a 1/rⁿ force gives T ∝ r^((n+1)/2); r^(3/2) is the inverse-square case.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-68","question":"Taking g = 10 m/s², the Earth's radius as 6400 km and G = 6.67 × 10⁻¹¹ N m² kg⁻², the mean density of the Earth works out to about:","options":["1.9 × 10³ kg/m³","5.6 × 10³ kg/m³","7.5 × 10³ kg/m³","1.1 × 10⁴ kg/m³"],"answer":1,"explanation":"g = GM/R² = (4/3)πGρR, so ρ = 3g/(4πGR) = 30/(4π × 6.67 × 10⁻¹¹ × 6.4 × 10⁶) ≈ 5.6 × 10³ kg/m³. Dropping the factor 3 gives 1.9 × 10³ kg/m³, and using ρ = g/(πGR) gives 7.5 × 10³ kg/m³.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-69","question":"Two concentric thin uniform spherical shells have masses M (radius R) and 2M (radius 2R). The gravitational potential at a distance 1.5R from their common centre is:","options":["−2GM/(3R)","−2GM/R","−5GM/(3R)","−GM/R"],"answer":2,"explanation":"Outside the inner shell it acts like a point mass: −GM/(1.5R) = −2GM/(3R). Inside the outer shell its potential is constant: −G(2M)/(2R) = −GM/R. Total = −5GM/(3R). −2GM/(3R) forgets that the outer shell still contributes potential, even though it gives no field there.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-70","question":"A planet moves in an elliptical orbit of period T with the Sun at one focus. The time it takes to go from perihelion to an end of the minor axis is:","options":["Exactly T/4","Exactly T/8","More than T/4","Less than T/4"],"answer":3,"explanation":"The area swept from perihelion to the end of the minor axis is a quarter of the ellipse minus a triangle (between the Sun, the centre and the end of the minor axis), so it is less than a quarter of the total area. By the law of equal areas the time is less than T/4: the planet moves fastest near perihelion.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-71","question":"A planet of radius R has a density that varies with distance r from its centre as ρ = k/r. The acceleration due to gravity at a depth R/2 below its surface, compared with the value g at the surface, is:","options":["g (the same)","g/4","g/2","2g"],"answer":0,"explanation":"M(r) = ∫ 4πr²(k/r) dr = 2πkr², so g(r) = GM(r)/r² = 2πGk, which is independent of r. g is the same at every depth. g/2 is the answer for a uniform planet.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-72","question":"A planet of radius R has a density that decreases linearly from ρ₀ at the centre to zero at the surface: ρ = ρ₀(1 − r/R). The acceleration due to gravity inside it is greatest at a distance from the centre of:","options":["R/2","2R/3","3R/4","R"],"answer":1,"explanation":"M(r) = 4πρ₀(r³/3 − r⁴/4R), so g(r) = GM(r)/r² ∝ r/3 − r²/(4R). Setting dg/dr = 0: 1/3 − r/(2R) = 0, r = 2R/3. For a uniform planet the maximum would be at the surface.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-73","question":"If the Earth were suddenly stopped in its (nearly circular) orbit, it would fall straight into the Sun. Taking the year as 365 days, the time it would take is about:","options":["129 days","91 days","65 days","183 days"],"answer":2,"explanation":"The straight fall is a limiting ellipse with semi-major axis R/2. By Kepler's third law its period is T/(2√2), and the fall is half of that orbit: T/(4√2) = 365/5.66 ≈ 65 days. 91 days is a quarter of a year; 129 days is the full degenerate-orbit period.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-gravitation-74", "question": "How many of the following statements about a thin uniform spherical shell of mass M and radius R are correct?\n(A) The gravitational field is zero at every point inside the shell.\n(B) The gravitational potential is zero at every point inside the shell.\n(C) The field changes abruptly from 0 just inside the shell to GM/R² just outside it.\n(D) The potential also changes abruptly as one crosses the shell.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 2, "explanation": "A and C are correct. Inside, the potential is constant at −GM/R, not zero, so B is wrong. The potential is continuous at the shell (−GM/R on both sides); only the field jumps, so D is wrong.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-75","question":"A particle is projected from the Earth's surface with speed √(gR) at 30° to the vertical (R = radius of the Earth; ignore the Earth's rotation and air). The greatest height it reaches above the surface is:","options":["R","R/2","3R/8","(√3/2)R"],"answer":3,"explanation":"Energy per unit mass: ½gR − gR = −gR/2. Angular momentum: R√(gR) sin 30° = r v at the top. Solving gives 4x² − 8x + 1 = 0 with x = r/R, so x = 1 + √3/2 and h = (√3/2)R ≈ 0.87R. R would be the height for a vertical launch, and 3R/8 uses the flat-Earth formula (v cos 30°)²/2g.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-76","question":"Two satellites move in coplanar circular orbits of radii R and 4R about the same planet, in the same sense. The period of the inner one is T. The time between successive instants when the two are lined up with the planet on the same side is:","options":["8T/7","7T/8","7T","8T/9"],"answer":0,"explanation":"The outer satellite's period is 8T (T ∝ r^(3/2)). The relative angular speed is 2π/T − 2π/8T, so the time between alignments = 1/(1/T − 1/8T) = 8T/7. 8T/9 would apply if they moved in opposite senses.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-gravitation-77", "question": "How many of the following statements about planetary motion are correct?\n(A) A planet moves fastest when it is closest to the Sun.\n(B) The period of a planet depends only on the semi-major axis of its orbit (for the same Sun).\n(C) The areal velocity of a planet equals L/(2m), where L is its angular momentum and m its mass.\n(D) For orbits with the same semi-major axis, the total energy of a planet is greater (less negative) for a more eccentric orbit.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "A, B and C are correct. D is wrong: the total energy is E = −GMm/(2a), which depends only on the semi-major axis, not on the eccentricity.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-78","question":"Match each quantity (List I) for a mass M of radius R with its value (List II).\nList I: (P) gravitational self-energy of a uniform solid sphere; (Q) gravitational self-energy of a thin uniform spherical shell; (R) gravitational potential at the centre of a uniform solid sphere; (S) gravitational potential at the centre of a thin uniform shell.\nList II: (1) −GM/R; (2) −3GM/(2R); (3) −GM²/(2R); (4) −3GM²/(5R).","options":["P–3, Q–4, R–2, S–1","P–4, Q–3, R–2, S–1","P–4, Q–3, R–1, S–2","P–2, Q–1, R–4, S–3"],"answer":1,"explanation":"Solid sphere: U = −3GM²/(5R) and V(centre) = −3GM/(2R). Thin shell: U = −GM²/(2R) (each element sits at potential −GM/R, and the factor ½ avoids double counting) and V(centre) = −GM/R. Energies carry M², potentials M.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-79","question":"A satellite moves in a circular orbit of radius r around a planet. If the planet's mass were suddenly doubled (with no impulse on the satellite), the satellite's nearest distance from the planet's centre in its new orbit would be:","options":["r/2","r","r/3","2r/3"],"answer":2,"explanation":"The speed √(GM/r) is now only 1/√2 of the new circular speed √(2GM/r), so the present point becomes the farthest point (apoapsis). With v² = k²(GM′/r) and k² = 1/2, the other end of the ellipse is at r k²/(2 − k²) = r(1/2)/(3/2) = r/3. r/2 comes from simply scaling the radius by the mass ratio.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-gravitation-80", "question": "Two particles, each of mass m, are released from rest a distance d apart in free space and move towards each other under their mutual gravity. When they are d/2 apart, the speed of each is:", "options": ["√(2Gm/d)", "√(Gm/(2d))", "√(Gm/d)", "2√(Gm/d)"], "answer": 2, "explanation": "Energy: −Gm²/d = −2Gm²/d + 2 × ½mv², so mv² = Gm²/d and v = √(Gm/d). √(2Gm/d) gives all the kinetic energy to one particle, though the two share it equally.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-81","question":"The gravitational field at the centre of the flat face of a uniform solid hemisphere of mass M and radius R is:","options":["GM/R²","GM/(2R²)","3GM/(4R²)","3GM/(2R²)"],"answer":3,"explanation":"Using spherical shells of radius r about the centre: a shell of thickness dr gives a field Gρ dr × ∫cos θ dΩ over a hemisphere = πGρ dr along the axis. Integrating from 0 to R gives πGρR, with ρ = 3M/(2πR³): g = 3GM/(2R²). GM/R² treats the hemisphere as a point mass at distance R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-gravitation-82", "question": "A planet of radius R has a core of radius R/2 with density 2ρ, surrounded by a mantle of density ρ. The ratio of g at the surface of the core to g at the surface of the planet is:", "options": ["8/9", "9/8", "1/2", "2/9"], "answer": 0, "explanation": "With V = (4/3)πR³: core mass = 2ρ(V/8) = ρV/4; mantle mass = ρ(7V/8); total = 9ρV/8. g(core) = G(ρV/4)/(R/2)² = GρV/R²; g(surface) = G(9ρV/8)/R². Ratio = 8/9. For a uniform planet the ratio would be 1/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-gravitation-83","question":"A comet's closest and farthest distances from the Sun are 0.5 AU and 31.5 AU. Its orbital period is:","options":["45 years","64 years","32 years","181 years"],"answer":1,"explanation":"Semi-major axis a = (0.5 + 31.5)/2 = 16 AU. Kepler's third law in years and AU: T = a^(3/2) = 16^(3/2) = 64 years. Taking the sum of the two distances (32 AU) as the semi-major axis gives 32^(3/2) ≈ 181 years.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-84","question":"Two identical satellites move in the same circular orbit round the Earth but in opposite senses. They collide head-on and stick together. Immediately after the collision the wreck:","options":["Continues in the same circular orbit","Moves into a larger elliptical orbit","Falls straight (radially) towards the Earth","Escapes from the Earth"],"answer":2,"explanation":"Equal masses with equal and opposite velocities have zero total momentum, so the wreck is momentarily at rest at that point and falls radially under gravity. Kinetic energy is not conserved in a sticking collision, so no orbit is kept.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-85","question":"At the equator, a rocket is launched with the least speed needed to escape from the Earth, once eastward and once westward. Taking the Earth's radius as 6400 km and its rotation period as 24 h, the difference between the two launch speeds measured relative to the ground is about:","options":["0.47 km/s","0","1.86 km/s","0.93 km/s"],"answer":3,"explanation":"Escape needs 11.2 km/s relative to an inertial frame. The ground at the equator moves east at ωR = (2π/86 400) × 6.4 × 10⁶ ≈ 0.465 km/s. Eastward you need 11.2 − 0.465 relative to the ground, westward 11.2 + 0.465: a difference of 2ωR ≈ 0.93 km/s. Zero ignores the Earth's rotation; 0.47 km/s gives only the saving in one direction.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-gravitation-86","question":"Two lead spheres attract each other gravitationally in air. If the space between them is filled with water, the gravitational force between them:","options":["decreases, because water screens gravity","remains the same","increases by a factor equal to the density of water","becomes zero"],"answer":1,"explanation":"G is a universal constant and gravity cannot be screened or modified by an intervening medium (unlike the electric force, which depends on permittivity). The force GMm/r² is unchanged; only buoyancy-type effects would alter the net force on the spheres.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-gravitation-87","question":"Two satellites, one of mass 100 kg and the other of 1000 kg, move in circular orbits of the same radius around the Earth. Compared with the lighter one, the heavier satellite has:","options":["the same orbital speed and period","a smaller orbital speed","a larger orbital speed","a shorter period"],"answer":0,"explanation":"GMm/r² = mv²/r gives v = √(GM/r), which does not involve the satellite's mass m. The period 2πr/v is therefore also the same; only energies and momenta scale with m.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-gravitation-88","question":"At what depth below the surface of a uniform Earth (radius R) is the acceleration due to gravity equal to its value at a height R/2 ABOVE the surface?","options":["4R/9","R/2","R/4","5R/9"],"answer":3,"explanation":"At height R/2: g′ = g/(1.5)² = 4g/9 (exact, not the small-h approximation). At depth d: g(1 − d/R) = 4g/9, so d = 5R/9 ≈ 3560 km. The rule 'd = 2h' only holds for h ≪ R.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-89","question":"A satellite moves in a circular orbit where the acceleration due to the Earth's gravity is one-ninth of its surface value (g = 10 m/s², R = 6400 km). Its period is about:","options":["1.4 h","4.2 h","7.3 h","12.6 h"],"answer":2,"explanation":"g/9 occurs at r = 3R. T = 2π√(r³/GM) = 2π√(27R³/gR²) = 2π√(27R/g) ≈ 2.61 × 10⁴ s ≈ 7.3 h, i.e. √27 times the 84-minute near-surface period.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-90","question":"A 1000 kg satellite moves in a circular orbit at a height equal to the Earth's radius (R = 6400 km, g = 10 m/s²). The minimum energy that must be supplied to make it escape the Earth's gravity from this orbit is:","options":["6.4 × 10¹⁰ J","3.2 × 10¹⁰ J","1.6 × 10¹⁰ J","8 × 10⁹ J"],"answer":2,"explanation":"In orbit at r = 2R the total energy is −GMm/2r = −GMm/4R = −mgR/4. To escape, the total energy must be raised to zero, so the energy needed is mgR/4 = 1000 × 10 × 6.4 × 10⁶/4 = 1.6 × 10¹⁰ J.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-91","question":"With what minimum speed must a body be projected vertically upward from the Earth's surface so that it rises to a height R/2 (R = 6400 km, g = 10 m/s², no air resistance)?","options":["5.66 km/s","6.53 km/s","8 km/s","9.24 km/s"],"answer":1,"explanation":"Energy: ½v² = GM/R − GM/(1.5R) = GM/3R = gR/3. So v = √(2gR/3) = √(4.27 × 10⁷) ≈ 6.53 km/s. Using mgh with constant g would overestimate the speed (8 km/s).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-92","question":"A satellite moves in a circular orbit of radius r₀. Its engine fires briefly, increasing its speed tangentially by a factor √(3/2). The greatest distance from the planet's centre in its new orbit is:","options":["3r₀","1.5r₀","2r₀","it escapes to infinity"],"answer":0,"explanation":"r₀ becomes the perigee. Using conservation of angular momentum and energy between perigee and apogee, v_p² = (GM/r₀)·2r_a/(r₀ + r_a). With v_p² = (3/2)GM/r₀: 3/2 = 2r_a/(r₀ + r_a), so r_a = 3r₀. Escape would need a factor √2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-93","question":"The gravitational field at the centre of a thin uniform semicircular ring of mass M and radius R has magnitude:","options":["zero","GM/R²","GM/(πR²)","2GM/(πR²)"],"answer":3,"explanation":"With λ = M/πR, an element at angle θ gives a field Gλ R dθ/R². The components along the symmetry axis add: E = (Gλ/R)∫₀^π sin θ dθ = 2Gλ/R = 2GM/(πR²). The perpendicular components cancel.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-94","question":"Three identical stars, each of mass M, form an equilateral triangle of side a and rotate about its centre under their mutual gravity, keeping the shape. The speed of each star is:","options":["√(GM/(√3a))","√(2GM/a)","√(3GM/a)","√(GM/a)"],"answer":3,"explanation":"Each star is at r = a/√3 from the centre, and the net pull of the other two is 2(GM²/a²)cos 30° = √3GM²/a² towards the centre. Setting Mv²/r = √3GM²/a² gives v² = √3GM(a/√3)/a² = GM/a.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-95","question":"In a region the gravitational potential is V = 5x² J/kg (x in metres), independent of y and z. A particle released from rest at x = 2 m moves along the x-axis. Its maximum speed is:","options":["10 m/s","√10 m/s","2√10 m/s ≈ 6.3 m/s","20 m/s"],"answer":2,"explanation":"The field is E = −dV/dx = −10x, so the acceleration −10x is simple harmonic with ω = √10 rad/s. From rest at amplitude 2 m, v_max = ωA = 2√10 ≈ 6.3 m/s (equivalently ½v² = V(2) − V(0) = 20 J/kg).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-96","question":"A tunnel is dug along a diameter of a uniform Earth (R = 6400 km, g = 10 m/s²). A particle is released from rest at a height R above the surface, directly above the tunnel. Its speed as it passes the Earth's centre is about:","options":["8 km/s","11.3 km/s","5.7 km/s","13.9 km/s"],"answer":1,"explanation":"Potential at r = 2R is −GM/2R; at the centre it is −3GM/2R. The drop is GM/R = gR, so ½v² = gR and v = √(2gR) = √(1.28 × 10⁸) ≈ 11.3 km/s, equal to the escape speed.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-97","question":"A small moon orbits a planet in a circle of radius 1.0 × 10⁷ m with a period of 2π × 10⁴ s. Taking G = 6.67 × 10⁻¹¹ N m² kg⁻², the mass of the planet is about:","options":["1.5 × 10²³ kg","1.5 × 10²¹ kg","6.0 × 10²⁴ kg","9.4 × 10²³ kg"],"answer":0,"explanation":"Kepler's third law: GM = 4π²r³/T² = r³/(T/2π)² = 10²¹/10⁸ = 10¹³ m³/s². So M = 10¹³/(6.67 × 10⁻¹¹) ≈ 1.5 × 10²³ kg.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-98","question":"A 60 kg person is weighed with an accurate spring balance first at a pole and then at the equator (treat the Earth as a uniform sphere of radius 6400 km with a 24 h rotation period). The equatorial reading is less by about:","options":["2.0 N","0.034 N","20 N","0.2 N"],"answer":0,"explanation":"At the equator the balance supplies mg − mω²R. With ω = 2π/86400 = 7.27 × 10⁻⁵ rad/s, ω²R ≈ 0.034 m/s², so the difference is 60 × 0.034 ≈ 2.0 N. (0.034 N forgets the mass.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-99","question":"An astronaut in a spaceship moving in a circular orbit gently releases a ball outside the ship, with zero velocity relative to the ship. The ball will:","options":["move away from the Earth and escape","fall towards the Earth","fly off tangentially in a straight line","keep moving alongside the ship in the same orbit"],"answer":3,"explanation":"Released with zero relative velocity, the ball has the same position and velocity as the ship, so it has exactly the orbital speed for that radius. Its motion, independent of its mass, is the same circular orbit, so it stays alongside.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-100","question":"A thin uniform rod of mass m and length L lies along a radial line outside a uniform solid sphere of mass M, its nearer end at distance d from the sphere's centre. The gravitational force between them is:","options":["GMm/(d + L/2)²","GMm/d²","GMm/[d(d + L)]","GMm/(d + L)²"],"answer":2,"explanation":"The sphere acts as a point mass at its centre. Integrating over the rod: F = ∫GM(m/L)dx/x² from d to d + L = (GMm/L)[1/d − 1/(d + L)] = GMm/[d(d + L)], the product of the end distances (not the square of the distance to the rod's midpoint).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-101","question":"A satellite moves in an elliptical orbit with semi-major axis a around a planet of mass M. At the instant it passes an end of the MINOR axis, its speed is:","options":["√(2GM/a)","√(GM/a), the speed of a circular orbit of radius a","√(GM/2a)","it depends on the eccentricity"],"answer":1,"explanation":"Vis-viva: v² = GM(2/r − 1/a). At an end of the minor axis the distance from the focus is exactly a (since b² + c² = a²). So v² = GM(2/a − 1/a) = GM/a, independent of the eccentricity.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-102","question":"Point masses 4M and M are fixed 3 m apart. At the point between them where the gravitational field is zero, the gravitational potential (in J/kg, with M in kg) is:","options":["zero","−3GM","−5GM/3","−6GM"],"answer":1,"explanation":"Null point: 4M/x² = M/(3 − x)², so x = 2 m from 4M (1 m from M). Potential is a scalar sum and never cancels: V = −G(4M/2 + M/1) = −3GM. Zero field does not mean zero potential.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-103","question":"A satellite in a circular orbit receives a brief impulse directed radially outward (away from the planet). Immediately afterwards, which quantity of the satellite is unchanged?","options":["Its angular momentum about the planet's centre","Its kinetic energy","Its total mechanical energy","Its speed"],"answer":0,"explanation":"A radial impulse exerts no torque about the planet's centre (r × J = 0), so L = mr v_tangential is unchanged. The radial velocity it adds increases the speed, the kinetic energy and the total energy, and the orbit becomes an ellipse.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-104","question":"A planet has one-quarter of the Earth's radius and twice its mean density. If g on the Earth is 10 m/s², the acceleration due to gravity at the planet's surface is:","options":["2.5 m/s²","20 m/s²","1.25 m/s²","5 m/s²"],"answer":3,"explanation":"g = GM/R² = (4/3)πGρR, so g ∝ ρR. The factor is 2 × 1/4 = 1/2, giving 5 m/s².","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-105","question":"Satellite P (mass m) and satellite Q (mass 2m) move in circular orbits of radii r and 4r about the same planet. The ratio of the angular momentum of P to that of Q is:","options":["1 : 8","1 : 2","1 : 4","2 : 1"],"answer":2,"explanation":"L = mvr with v = √(GM/r), so L = m√(GMr). Ratio = m√r : 2m√(4r) = 1 : 4.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-106","question":"A satellite skimming the surface of an airless planet has an orbital speed of 4 km/s. The escape speed from the planet's surface is about:","options":["4 km/s","8 km/s","5.66 km/s","11.2 km/s"],"answer":2,"explanation":"Near the surface v_orbit = √(GM/R) and v_escape = √(2GM/R), so v_escape = √2 × 4 ≈ 5.66 km/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-107","question":"The gravitational field in a region is uniform and equal to (2î + 3ĵ) N/kg. The work done by the field on a 2 kg body moved from the origin to the point (3 m, −2 m) is:","options":["24 J","zero","12 J","−12 J"],"answer":1,"explanation":"W = mE·d = 2 × (2 × 3 + 3 × (−2)) = 2 × 0 = 0. The displacement is perpendicular to the field, so both points lie on the same equipotential.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-108","question":"A uniform solid hemisphere has mass M and radius R. The gravitational potential at the centre of its flat face is:","options":["−3GM/2R","−GM/R","−3GM/4R","−GM/2R"],"answer":0,"explanation":"Two such hemispheres make a full sphere of mass 2M, whose potential at its centre is −3G(2M)/2R = −3GM/R. Each half contributes equally by symmetry (potential is a scalar), so one hemisphere gives −3GM/2R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-109","question":"A satellite circles a planet with period T. If the planet's mass were four times larger and the orbit radius twice as large, the period would be:","options":["2√2 T","2T","T/√2","√2 T"],"answer":3,"explanation":"T = 2π√(r³/GM), so T ∝ r^(3/2) M^(−1/2). The factor is 2^(3/2)/√4 = 2√2/2 = √2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-110","question":"A pendulum clock keeps correct time on the Earth's surface. It is taken to a height equal to the Earth's radius (in a laboratory that is somehow held stationary there). In what would be one full day of correct time, the clock shows:","options":["48 hours","6 hours","18 hours","12 hours, i.e. it loses 12 hours"],"answer":3,"explanation":"At height R, g′ = g/4, so the period T ∝ 1/√g doubles. The clock completes half as many swings, recording only 12 h in 24 h of real time.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-111","question":"A thin uniform disc of radius R has surface mass density σ. The gravitational field on its axis at a distance R/√3 from its centre is:","options":["πGσ/2","2πGσ","πGσ","(2 − √3)πGσ"],"answer":2,"explanation":"On the axis at distance x, E = 2πGσ[1 − x/√(x² + R²)]. At x = R/√3, x/√(x² + R²) = (R/√3)/(2R/√3) = 1/2, so E = 2πGσ × 1/2 = πGσ.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-112","question":"A planet moves in an elliptical orbit of eccentricity 0.5. The fraction of its period it spends on the half of the orbit nearer the Sun, between the two ends of the minor axis, is about:","options":["0.5","0.34","0.25","0.66"],"answer":1,"explanation":"By Kepler's second law, time ∝ area swept from the Sun. The near half of the ellipse has area πab/2, minus the triangle formed by the Sun and the minor-axis ends (area ab·e). Fraction = (πab/2 − abe)/(πab) = 1/2 − e/π ≈ 0.5 − 0.159 = 0.34.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-113","question":"The Earth's mass is 81 times the Moon's and their centres are 3.84 × 10⁵ km apart (Earth's radius 6400 km). The centre of mass of the Earth–Moon system lies:","options":["about 4700 km from the Earth's centre, inside the Earth","about 1.9 × 10⁵ km from the Earth's centre","at the Earth's surface","about 4700 km from the Moon's centre"],"answer":0,"explanation":"x_cm = m_moon d/(M + m) = d/82 = 3.84 × 10⁵/82 ≈ 4.7 × 10³ km from the Earth's centre. This is less than 6400 km, so the point about which both bodies orbit lies within the Earth.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-114","question":"A spring balance reads 720 N for an astronaut on the Earth's surface. Ignoring rotation, what would it read if the astronaut stood on a tower of height 0.2R (R = Earth's radius)?","options":["500 N","576 N","600 N","432 N"],"answer":0,"explanation":"g ∝ 1/r², so at r = 1.2R the reading is 720/1.44 = 500 N. The linear approximation g(1 − 2h/R) would give 432 N, which is badly wrong for h = 0.2R.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-gravitation-115","question":"Taking g = 10 m/s² at the Earth's surface and R = 6400 km, and assuming the Moon moves in a circle of radius 60R about the Earth's centre, the Moon's orbital period comes out to be about:","options":["60 days","30 days","24 days","27 days"],"answer":3,"explanation":"T = 2π√(r³/GM) with GM = gR²: T = 2π√(216000R/g) = 2π√(1.38 × 10¹¹) ≈ 2.34 × 10⁶ s ≈ 27 days, in agreement with the observed sidereal month.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-116","question":"For a thin uniform spherical shell of mass M and radius R, which statement about the gravitational field E and potential V as one crosses the shell from inside to outside is correct?","options":["E is continuous, but V jumps from −GM/R to 0","Both V and E are continuous at r = R","V is continuous at r = R, but E jumps from 0 to GM/R²","Both are zero inside the shell"],"answer":2,"explanation":"Inside the shell E = 0 everywhere and V = −GM/R (constant). Just outside, E = GM/R² and V = −GM/R. So the potential is continuous but the field has a jump of GM/R², the effect of the surface layer of mass.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-gravitation-117","question":"A probe is launched from the Earth's surface with twice the escape speed (escape speed 11.2 km/s), ignoring air resistance and other bodies. Its speed when it is very far from the Earth is about:","options":["11.2 km/s","19.4 km/s","22.4 km/s","15.8 km/s"],"answer":1,"explanation":"Energy: ½v_∞² = ½(2vₑ)² − ½vₑ², since ½vₑ² = GM/R is exactly the energy needed to climb out. So v_∞ = √3 vₑ ≈ 19.4 km/s, not 2vₑ − vₑ.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-gravitation-118","question":"A uniform solid sphere of mass M and radius R is imagined to be cut into two hemispheres. The gravitational force of attraction between the two halves is:","options":["GM²/4R²","3GM²/16R²","3GM²/8R²","GM²/R²"],"answer":1,"explanation":"A hemisphere exerts no net force on itself, so the force on it equals the force from the whole sphere. Inside a uniform sphere g = GMr/R³, so the force on one half is (GM/R³) × (M/2) × z_cm, with z_cm = 3R/8. This gives (GM/R³)(M/2)(3R/8) = 3GM²/16R².","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
